      "path": "SECURITY.md",
      "content": "# Security Policy\n\n## Reporting a Vulnerability / 报告漏洞\n\nPlease **do not** open a public issue for security vulnerabilities. / 安全漏洞请勿公开提 issue。\n\n- 私信 / Private message: [534119219](https://github.com/534119219)\n- 邮箱 / Email: 通过 GitHub 主页联系信息\n\nWe will respond within 7 days and coordinate a fix before any public disclosure. /\n我们会在 7 天内回复，并在公开披露前协调修复。\n\n## Security notes / 安全说明\n\n- 渠道配置（含 SendKey / Token / 授权码等密钥）明文存储在\n  `$DSH_HOME/push/channels.json`，请确保该目录仅当前用户可读写。\n- `/push/api/*` 接口有 fence 保护（仅同源 / loopback / 受信 host），\n  请勿将该端口暴露到不可信网络。\n- 邮件渠道的授权码只在调用时用于 SMTP 认证，不写入日志。\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * chicheng-push — host half\n *\n * A multi-channel message push plugin for the dsh web profile:\n *   - persists push channels under $DSH_HOME/push/channels.json\n *   - channel types follow the qinglong notify catalogue (Server酱, PushPlus,\n *     Bark, 钉钉机器人, 企业微信群机器人, 企业微信应用, Telegram, 飞书/Lark,\n *     ntfy, iGot, pushDeer, Gotify, 自定义 Webhook, 邮件(可选 nodemailer))\n *   - exposes a fenced JSON API at /push/api/<method> for the client half\n *   - provides the `pushNotifier` cordis service so OTHER plugins can push\n *     notifications, e.g. a cron task plugin calling\n *     `ctx.get(\"pushNotifier\").send({ title, content })` after a run\n *\n * No third-party runtime dependencies: HTTP channels use the built-in\n * `fetch`; the email channel dynamically imports nodemailer only when\n * configured and available.\n */\nimport { randomUUID } from \"node:crypto\";\nimport { createHmac } from \"node:crypto\";\nimport { mkdir, readFile, writeFile, rename } from \"node:fs/promises\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\n\n// ---------------------------------------------------------------- identity\n\nconst name = \"chicheng-push\";\nconst NS = \"chicheng-push\";\nconst inject = [\"webServer\", \"webRuntime\"];\n\n// ---------------------------------------------------------------- paths\n\nconst DATA_ROOT = process.env.DSH_HOME\n  ? join(process.env.DSH_HOME, \"push\")\n  : join(homedir(), \".dsh\", \"push\");\nconst STORE_PATH = join(DATA_ROOT, \"channels.json\");\n\n// ---------------------------------------------------------------- store\n\nconst EMPTY_STORE = { version: 1, channels: [] };\nlet store = structuredClone(EMPTY_STORE);\nlet storeDirtyTimer = null;\n\nasync function loadStore() {\n  try {\n    const raw = await readFile(STORE_PATH, \"utf8\");\n    const parsed = JSON.parse(raw);\n    if (parsed && Array.isArray(parsed.channels)) store = parsed;\n  } catch {\n    store = structuredClone(EMPTY_STORE);\n  }\n  if (!Array.isArray(store.channels)) store.channels = [];\n}\n\n/** Debounced atomic persist (tolerates crashes: tmp + rename). */\nfunction scheduleSave() {\n  if (storeDirtyTimer !== null) return;\n  storeDirtyTimer = setTimeout(() => {\n    storeDirtyTimer = null;\n    void flushStore();\n  }, 150);\n}\n\nasync function flushStore() {\n  try {\n    await mkdir(DATA_ROOT, { recursive: true });\n    const tmp = `${STORE_PATH}.tmp`;\n    await writeFile(tmp, JSON.stringify(store, null, 2), \"utf8\");\n    await rename(tmp, STORE_PATH);\n  } catch (error) {\n    console.error(`[chicheng-push] store flush failed:`, error);\n  }\n}\n\n// ---------------------------------------------------------------- util\n\nconst isPlainObject = (value) => value !== null && typeof value === \"object\" && !Array.isArray(value);\n\n/** Compact error text out of an unknown thrown value. */\nfunction errorText(error) {\n  if (error instanceof Error) return error.message;\n  return String(error);\n}\n\n/** Base64 first line of a UTF-8 string (used by the RFC2047 title header). */\nfunction encodeRfc2047(text) {\n  return `=?UTF-8?B?${Buffer.from(String(text)).toString(\"base64\")}?=`;\n}\n\n/** POST with the Node built-in fetch; JSON or form bodies, short timeout. */\nasync function httpJson(url, { method = \"POST\", json, form, headers = {}, raw } = {}) {\n  let body;\n  const finalHeaders = { ...headers };\n  if (raw !== undefined) {\n    body = raw;\n  } else if (json !== undefined) {\n    body = JSON.stringify(json);\n    finalHeaders[\"content-type\"] = \"application/json\";\n  } else if (form !== undefined) {\n    body = new URLSearchParams(form).toString();\n    finalHeaders[\"content-type\"] = \"application/x-www-form-urlencoded\";\n  }\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), 12000);\n  try {\n    const res = await fetch(url, {\n      method,\n      headers: finalHeaders,\n      body,\n      signal: controller.signal,\n      redirect: \"follow\",\n    });\n    const text = await res.text().catch(() => \"\");\n    let parsed = null;\n    try {\n      parsed = text === \"\" ? null : JSON.parse(text);\n    } catch {\n      parsed = null;\n    }\n    return { status: res.status, ok: res.ok, text, json: parsed };\n  } finally {\n    clearTimeout(timer);\n  }\n}\n\n// ---------------------------------------------------------------- channel registry\n//\n// Field shapes drive the dynamic client form:\n//   { key, label, type: 'text'|'password'|'textarea'|'number'|'select',\n//     options?, placeholder?, help?, required?, default? }\n\nconst CHANNEL_TYPES = [\n  {\n    id: \"serverChan\",\n    label: \"Server酱\",\n    help: \"https://sct.ftqq.com 获取 SendKey\",\n    fields: [\n      { key: \"serverChanKey\", label: \"SendKey\", type: \"password\", required: true, placeholder: \"SCTxxxxxxxxxxxxxxxxxxxx\" },\n    ],\n  },\n  {\n    id: \"pushPlus\",\n    label: \"PushPlus\",\n    help: \"https://www.pushplus.plus 获取 token\",\n    fields: [\n      { key: \"pushPlusToken\", label: \"Token\", type: \"password\", required: true },\n      { key: \"pushPlusUser\", label: \"群组编码（可选）\", type: \"text\" },\n      { key: \"pushplusChannel\", label: \"推送渠道（可选）\", type: \"text\", placeholder: \"wechat / webhook / cp / mail / sms\" },\n    ],\n  },\n  {\n    id: \"bark\",\n    label: \"Bark\",\n    help: \"iOS 推送，https://github.com/Finb/Bark\",\n    fields: [\n      { key: \"barkPush\", label: \"推送地址或设备 Key\", type: \"text\", required: true, placeholder: \"https://api.day.app/xxxxxxxx 或直接填 Key\" },\n      { key: \"barkIcon\", label: \"图标 URL（可选）\", type: \"text\" },\n      { key: \"barkSound\", label: \"铃声（可选）\", type: \"text\" },\n      { key: \"barkGroup\", label: \"分组（可选）\", type: \"text\" },\n      { key: \"barkLevel\", label: \"级别（可选）\", type: \"select\", options: [\"active\", \"timeSensitive\", \"passive\"] },\n      { key: \"barkArchive\", label: \"归档（可选）\", type: \"text\", placeholder: \"1 或留空\" },\n      { key: \"barkUrl\", label: \"点击跳转 URL（可选）\", type: \"text\" },\n    ],\n  },\n  {\n    id: \"dingtalkBot\",\n    label: \"钉钉机器人\",\n    help: \"群机器人 Webhook，https://open.dingtalk.com 可配置加签\",\n    fields: [\n      { key: \"dingtalkBotToken\", label: \"Access Token\", type: \"password\", required: true },\n      { key: \"dingtalkBotSecret\", label: \"加签 Secret（可选）\", type: \"password\", help: \"安全设置 → 加签 的密钥\" },\n    ],\n  },\n  {\n    id: \"weWorkBot\",\n    label: \"企业微信群机器人\",\n    help: \"群机器人 Webhook Key\",\n    fields: [\n      { key: \"weWorkBotKey\", label: \"Webhook Key\", type: \"password\", required: true },\n      { key: \"weWorkOrigin\", label: \"API 域名（可选）\", type: \"text\", placeholder: \"https://qyapi.weixin.qq.com\" },\n    ],\n  },\n  {\n    id: \"weWorkApp\",\n    label: \"企业微信应用消息\",\n    help: \"需自建应用，字段用逗号分隔\",\n    fields: [\n      { key: \"weWorkAppKey\", label: \"corpid,corpsecret,touser,agentid\", type: \"password\", required: true, placeholder: \"wwxxxxxxxx,secret,touser,1000002\" },\n      { key: \"weWorkOrigin\", label: \"API 域名（可选）\", type: \"text\", placeholder: \"https://qyapi.weixin.qq.com\" },\n    ],\n  },\n  {\n    id: \"telegramBot\",\n    label: \"Telegram Bot\",\n    help: \"BotFather 创建 Bot 获取 token\",\n    fields: [\n      { key: \"telegramBotToken\", label: \"Bot Token\", type: \"password\", required: true },\n      { key: \"telegramBotUserId\", label: \"Chat ID 或 User ID\", type: \"text\", required: true, placeholder: \"123456789\" },\n      { key: \"telegramBotApiHost\", label: \"API 域名（可选）\", type: \"text\", placeholder: \"https://api.telegram.org（默认）\" },\n    ],\n  },\n  {\n    id: \"lark\",\n    label: \"飞书/Lark 机器人\",\n    help: \"自定义机器人 Webhook，https://open.feishu.cn 可配置加签\",\n    fields: [\n      { key: \"larkKey\", label: \"Webhook 地址或 Key\", type: \"text\", required: true, placeholder: \"https://open.feishu.cn/open-apis/bot/v2/hook/xxxx\" },\n      { key: \"larkSecret\", label: \"加签 Secret（可选）\", type: \"password\" },\n    ],\n  },\n  {\n    id: \"ntfy\",\n    label: \"ntfy\",\n    help: \"https://ntfy.sh 或自建实例\",\n    fields: [\n      { key: \"ntfyUrl\", label: \"服务器地址（可选）\", type: \"text\", placeholder: \"https://ntfy.sh\" },\n      { key: \"ntfyTopic\", label: \"Topic\", type: \"text\", required: true },\n      { key: \"ntfyToken\", label: \"访问 Token（可选）\", type: \"password\" },\n      { key: \"ntfyUsername\", label: \"用户名（可选，与 Token 二选一）\", type: \"text\" },\n      { key: \"ntfyPassword\", label: \"密码（可选）\", type: \"password\" },\n      { key: \"ntfyPriority\", label: \"优先级（可选）\", type: \"select\", options: [\"1\", \"2\", \"3\", \"4\", \"5\"] },\n    ],\n  },\n  {\n    id: \"iGot\",\n    label: \"iGot\",\n    help: \"https://igot.app 聚合推送\",\n    fields: [\n      { key: \"iGotPushKey\", label: \"Push Key\", type: \"password\", required: true },\n    ],\n  },\n  {\n    id: \"pushDeer\",\n    label: \"PushDeer\",\n    help: \"https://www.pushdeer.com\",\n    fields: [\n      { key: \"pushDeerKey\", label: \"PushKey\", type: \"password\", required: true },\n      { key: \"pushDeerUrl\", label: \"自建地址（可选）\", type: \"text\", placeholder: \"https://api2.pushdeer.com/message/push\" },\n    ],\n  },\n  {\n    id: \"gotify\",\n    label: \"Gotify\",\n    help: \"自部署 https://gotify.net\",\n    fields: [\n      { key: \"gotifyUrl\", label: \"服务器地址\", type: \"text\", required: true, placeholder: \"https://gotify.example.com\" },\n      { key: \"gotifyToken\", label: \"应用 Token\", type: \"password\", required: true },\n      { key: \"gotifyPriority\", label: \"优先级（可选）\", type: \"select\", options: [\"0\", \"1\", \"2\", \"3\", \"4\", \"5\", \"6\", \"7\"] },\n    ],\n  },\n  {\n    id: \"webhook\",\n    label: \"自定义 Webhook\",\n    help: \"任意 HTTP 接口；URL/Body 中支持 $title 与 $content 变量\",\n    fields: [\n      { key: \"webhookUrl\", label: \"请求 URL\", type: \"text\", required: true, placeholder: \"https://example.com/hook?title=$title\" },\n      { key: \"webhookMethod\", label: \"请求方法\", type: \"select\", options: [\"POST\", \"GET\", \"PUT\", \"PATCH\"] },\n      { key: \"webhookContentType\", label: \"Content-Type\", type: \"select\", options: [\"application/json\", \"application/x-www-form-urlencoded\", \"text/plain\"] },\n      { key: \"webhookBody\", label: \"请求体模板（可选）\", type: \"textarea\", placeholder: '{\"text\": \"$title\\\\n$content\"}' },\n      { key: \"webhookHeaders\", label: \"请求头（可选，每行一个）\", type: \"textarea\", placeholder: \"Authorization: Bearer xxxxx\" },\n    ],\n  },\n  {\n    id: \"email\",\n    label: \"邮件（SMTP）\",\n    help: \"需要本环境可动态加载 nodemailer\",\n    fields: [\n      { key: \"emailService\", label: \"服务商\", type: \"text\", placeholder: \"QQ / 163 / Gmail 或留空填自定义 SMTP 主机\" },\n      { key: \"emailHost\", label: \"SMTP 主机（可选，service 留空时使用）\", type: \"text\" },\n      { key: \"emailPort\", label: \"端口（可选）\", type: \"number\", placeholder: \"465\" },\n      { key: \"emailSecure\", label: \"是否 SSL（可选）\", type: \"select\", options: [\"true\", \"false\"] },\n      { key: \"emailUser\", label: \"发件邮箱\", type: \"text\", required: true },\n      { key: \"emailPass\", label: \"邮箱授权码\", type: \"password\", required: true },\n      { key: \"emailTo\", label: \"收件人（多个用 ; 分隔）\", type: \"text\", required: true },\n    ],\n  },\n];\n\nconst TYPE_MAP = new Map(CHANNEL_TYPES.map((t) => [t.id, t]));\n\n/** Lookup sender for a channel type; throws on an unknown type. */\nfunction senderForType(typeId) {\n  switch (typeId) {\n    case \"serverChan\": return sendServerChan;\n    case \"pushPlus\": return sendPushPlus;\n    case \"bark\": return sendBark;\n    case \"dingtalkBot\": return sendDingtalkBot;\n    case \"weWorkBot\": return sendWeWorkBot;\n    case \"weWorkApp\": return sendWeWorkApp;\n    case \"telegramBot\": return sendTelegramBot;\n    case \"lark\": return sendLark;\n    case \"ntfy\": return sendNtfy;\n    case \"iGot\": return sendIGot;\n    case \"pushDeer\": return sendPushDeer;\n    case \"gotify\": return sendGotify;\n    case \"webhook\": return sendWebhook;\n    case \"email\": return sendEmail;\n    default: throw new Error(`未知渠道类型 \"${typeId}\"`);\n  }\n}\n\n// ---- qinglong-style channel implementations (zero-dependency; fetch-based)\n\nasync function sendServerChan(config, title, content) {\n  const key = String(config.serverChanKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少 ServerChan SendKey\");\n  const match = /^sctp(\\d+)t/i.exec(key);\n  const url = match && match[1]\n    ? `https://${match[1]}.push.ft07.com/send/${key}.send`\n    : `https://sctapi.ftqq.com/${key}.send`;\n  const res = await httpJson(url, { form: { title, desp: content } });\n  const errno = res.json?.errno ?? res.json?.data?.errno;\n  if (res.json && errno !== undefined && errno !== 0) {\n    throw new Error(`Server酱返回 errno=${errno}: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`Server酱 HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `Server酱已发送 (${res.status})`;\n}\n\nasync function sendPushPlus(config, title, content) {\n  const token = String(config.pushPlusToken ?? \"\").trim();\n  if (token === \"\") throw new Error(\"缺少 PushPlus Token\");\n  const res = await httpJson(\"https://www.pushplus.plus/send\", {\n    json: {\n      token,\n      title,\n      content: content.replace(/[\\n\\r]/g, \"<br>\"),\n      template: \"html\",\n      topic: String(config.pushPlusUser ?? \"\").trim(),\n      channel: String(config.pushplusChannel ?? \"\").trim() || \"wechat\",\n    },\n  });\n  if (res.json && res.json.code !== 200) {\n    throw new Error(`PushPlus 返回 code=${res.json.code}: ${res.json.msg ?? res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`PushPlus HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `PushPlus已发送 (${res.status})`;\n}\n\nasync function sendBark(config, title, content) {\n  let push = String(config.barkPush ?? \"\").trim();\n  if (push === \"\") throw new Error(\"缺少 Bark 推送地址\");\n  if (!/^https?:\\/\\//i.test(push)) push = `https://api.day.app/${push}`;\n  const body = {\n    title,\n    body: content,\n    icon: String(config.barkIcon ?? \"\"),\n    sound: String(config.barkSound ?? \"\"),\n    group: String(config.barkGroup ?? \"\"),\n    isArchive: String(config.barkArchive ?? \"\"),\n    level: String(config.barkLevel ?? \"\"),\n    url: String(config.barkUrl ?? \"\"),\n  };\n  const res = await httpJson(push, { json: body });\n  if (res.json && res.json.code !== 200) {\n    throw new Error(`Bark 返回 code=${res.json.code}: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`Bark HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `Bark已发送 (${res.status})`;\n}\n\nasync function sendDingtalkBot(config, title, content) {\n  const token = String(config.dingtalkBotToken ?? \"\").trim();\n  if (token === \"\") throw new Error(\"缺少钉钉机器人 Access Token\");\n  let url = `https://oapi.dingtalk.com/robot/send?access_token=${encodeURIComponent(token)}`;\n  const secret = String(config.dingtalkBotSecret ?? \"\").trim();\n  if (secret !== \"\") {\n    const timestamp = Date.now();\n    const hmac = createHmac(\"sha256\", secret);\n    hmac.update(`${timestamp}\\n${secret}`);\n    const sign = encodeURIComponent(hmac.digest(\"base64\"));\n    url += `&timestamp=${timestamp}&sign=${sign}`;\n  }\n  const res = await httpJson(url, { json: { msgtype: \"text\", text: { content: `${title}\\n\\n${content}` } } });\n  if (res.json && res.json.errcode !== 0) {\n    throw new Error(`钉钉返回 errcode=${res.json.errcode}: ${res.json.errmsg ?? res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`钉钉 HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `钉钉已发送 (${res.status})`;\n}\n\nasync function sendWeWorkBot(config, title, content) {\n  const key = String(config.weWorkBotKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少企业微信群机器人 Key\");\n  const origin = (String(config.weWorkOrigin ?? \"\").trim() || \"https://qyapi.weixin.qq.com\").replace(/\\/+$/, \"\");\n  const res = await httpJson(`${origin}/cgi-bin/webhook/send?key=${encodeURIComponent(key)}`, {\n    json: { msgtype: \"text\", text: { content: `${title}\\n\\n${content}` } },\n  });\n  if (res.json && res.json.errcode !== 0) {\n    throw new Error(`企业微信返回 errcode=${res.json.errcode}: ${res.json.errmsg ?? res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`企业微信 HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `企业微信群机器人已发送 (${res.status})`;\n}\n\nasync function sendWeWorkApp(config, title, content) {\n  const key = String(config.weWorkAppKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少企业微信应用参数\");\n  const [corpid, corpsecret, touser, agentid] = key.split(\",\").map((s) => s.trim());\n  if (!corpid || !corpsecret || !touser || !agentid) {\n    throw new Error(\"企业微信应用参数需为 corpid,corpsecret,touser,agentid 四段\");\n  }\n  const origin = (String(config.weWorkOrigin ?? \"\").trim() || \"https://qyapi.weixin.qq.com\").replace(/\\/+$/, \"\");\n  const tokenRes = await httpJson(`${origin}/cgi-bin/gettoken`, { json: { corpid, corpsecret } });\n  const accessToken = tokenRes.json?.access_token;\n  if (!accessToken) {\n    throw new Error(`获取企业微信 token 失败: ${tokenRes.text.slice(0, 300)}`);\n  }\n  const res = await httpJson(`${origin}/cgi-bin/message/send?access_token=${accessToken}`, {\n    json: { touser, agentid, safe: \"0\", msgtype: \"text\", text: { content: `${title}\\n\\n${content}` } },\n  });\n  if (res.json && res.json.errcode !== 0) {\n    throw new Error(`企业微信发送返回 errcode=${res.json.errcode}: ${res.json.errmsg ?? res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`企业微信 HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `企业微信应用已发送 (${res.status})`;\n}\n\nasync function sendTelegramBot(config, title, content) {\n  const token = String(config.telegramBotToken ?? \"\").trim();\n  const chatId = String(config.telegramBotUserId ?? \"\").trim();\n  if (token === \"\" || chatId === \"\") throw new Error(\"缺少 Telegram Bot Token 或 Chat ID\");\n  const apiHost = (String(config.telegramBotApiHost ?? \"\").trim() || \"https://api.telegram.org\").replace(/\\/+$/, \"\");\n  const res = await httpJson(`${apiHost}/bot${token}/sendMessage`, {\n    form: { chat_id: chatId, text: `${title}\\n\\n${content}`, disable_web_page_preview: \"true\" },\n  });\n  if (res.json && res.json.ok !== true) {\n    throw new Error(`Telegram 返回: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`Telegram HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `Telegram已发送 (${res.status})`;\n}\n\nasync function sendLark(config, title, content) {\n  let key = String(config.larkKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少飞书 Webhook 地址\");\n  if (!/^https?:\\/\\//i.test(key)) key = `https://open.feishu.cn/open-apis/bot/v2/hook/${key}`;\n  const body = { msg_type: \"text\", content: { text: `${title}\\n\\n${content}` } };\n  const secret = String(config.larkSecret ?? \"\").trim();\n  if (secret !== \"\") {\n    const timestamp = Math.floor(Date.now() / 1000).toString();\n    const stringToSign = `${timestamp}\\n${secret}`;\n    const hmac = createHmac(\"sha256\", stringToSign);\n    body.timestamp = timestamp;\n    body.sign = hmac.digest(\"base64\");\n  }\n  const res = await httpJson(key, { json: body });\n  const code = res.json?.StatusCode ?? res.json?.code;\n  if (res.json && code !== undefined && code !== 0) {\n    throw new Error(`飞书返回 code=${code}: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`飞书 HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `飞书已发送 (${res.status})`;\n}\n\nasync function sendNtfy(config, title, content) {\n  const topic = String(config.ntfyTopic ?? \"\").trim();\n  if (topic === \"\") throw new Error(\"缺少 ntfy Topic\");\n  const base = (String(config.ntfyUrl ?? \"\").trim() || \"https://ntfy.sh\").replace(/\\/+$/, \"\");\n  const headers = { Title: encodeRfc2047(title), Priority: String(config.ntfyPriority ?? \"3\") || \"3\" };\n  const token = String(config.ntfyToken ?? \"\").trim();\n  const username = String(config.ntfyUsername ?? \"\").trim();\n  const password = String(config.ntfyPassword ?? \"\");\n  if (token !== \"\") headers.Authorization = `Bearer ${token}`;\n  else if (username !== \"\" && password !== \"\") headers.Authorization = `Basic ${Buffer.from(`${username}:${password}`).toString(\"base64\")}`;\n  const res = await httpJson(`${base}/${topic}`, { headers, raw: content });\n  if (!res.ok) throw new Error(`ntfy HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `ntfy已发送 (${res.status})`;\n}\n\nasync function sendIGot(config, title, content) {\n  const key = String(config.iGotPushKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少 iGot Push Key\");\n  const res = await httpJson(`https://push.hellyw.com/${key.toLowerCase()}`, { form: { title, content } });\n  if (res.json && res.json.ret !== 0) {\n    throw new Error(`iGot 返回 ret=${res.json.ret}: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`iGot HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `iGot已发送 (${res.status})`;\n}\n\nasync function sendPushDeer(config, title, content) {\n  const key = String(config.pushDeerKey ?? \"\").trim();\n  if (key === \"\") throw new Error(\"缺少 PushDeer PushKey\");\n  const url = String(config.pushDeerUrl ?? \"\").trim() || \"https://api2.pushdeer.com/message/push\";\n  const res = await httpJson(url, { form: { pushkey: key, text: title, desp: content, type: \"markdown\" } });\n  if (res.json && res.json.errno !== 0) {\n    throw new Error(`PushDeer 返回 errno=${res.json.errno}: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`PushDeer HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `PushDeer已发送 (${res.status})`;\n}\n\nasync function sendGotify(config, title, content) {\n  const url = String(config.gotifyUrl ?? \"\").trim().replace(/\\/+$/, \"\");\n  const token = String(config.gotifyToken ?? \"\").trim();\n  if (url === \"\" || token === \"\") throw new Error(\"缺少 Gotify 地址或 Token\");\n  const res = await httpJson(`${url}/message?token=${encodeURIComponent(token)}`, {\n    form: { title, message: content, priority: String(config.gotifyPriority ?? \"1\") },\n  });\n  if (res.json && typeof res.json.id !== \"number\") {\n    throw new Error(`Gotify 返回异常: ${res.text.slice(0, 300)}`);\n  }\n  if (!res.ok && !res.json) throw new Error(`Gotify HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `Gotify已发送 (${res.status})`;\n}\n\n/** Parse \"Key: value\" lines into a headers object. */\nfunction parseHeaders(text) {\n  const headers = {};\n  for (const line of String(text ?? \"\").split(/\\r?\\n/)) {\n    const idx = line.indexOf(\":\");\n    if (idx <= 0) continue;\n    const key = line.slice(0, idx).trim();\n    const value = line.slice(idx + 1).trim();\n    if (key !== \"\") headers[key] = value;\n  }\n  return headers;\n}\n\nasync function sendWebhook(config, title, content) {\n  const urlTemplate = String(config.webhookUrl ?? \"\").trim();\n  if (urlTemplate === \"\") throw new Error(\"缺少 Webhook URL\");\n  const url = urlTemplate\n    .replaceAll(\"$title\", encodeURIComponent(title))\n    .replaceAll(\"$content\", encodeURIComponent(content));\n  const method = String(config.webhookMethod ?? \"\").trim() || \"POST\";\n  const contentType = String(config.webhookContentType ?? \"\").trim() || \"application/json\";\n  const headers = parseHeaders(config.webhookHeaders);\n  const bodyTemplate = String(config.webhookBody ?? \"\");\n  const bodyText = bodyTemplate\n    .replaceAll(\"$title\", title)\n    .replaceAll(\"$content\", content);\n\n  let raw;\n  if (contentType === \"application/json\" && bodyText.trim() !== \"\") {\n    try {\n      raw = JSON.stringify(JSON.parse(bodyText));\n    } catch {\n      raw = bodyText;\n    }\n    if (!Object.keys(headers).some((k) => k.toLowerCase() === \"content-type\")) {\n      headers[\"content-type\"] = contentType;\n    }\n  } else {\n    raw = bodyText;\n    if (!Object.keys(headers).some((k) => k.toLowerCase() === \"content-type\")) {\n      headers[\"content-type\"] = contentType;\n    }\n  }\n  const res = await httpJson(url, { method, headers, raw });\n  if (!res.ok) throw new Error(`Webhook HTTP ${res.status}: ${res.text.slice(0, 300)}`);\n  return `Webhook已发送 (${res.status})`;\n}\n\nasync function sendEmail(config, title, content) {\n  const user = String(config.emailUser ?? \"\").trim();\n  const pass = String(config.emailPass ?? \"\");\n  const to = String(config.emailTo ?? \"\").trim();\n  if (user === \"\" || pass === \"\" || to === \"\") throw new Error(\"缺少邮件发件人、授权码或收件人\");\n  let nodemailer;\n  try {\n    nodemailer = (await import(\"nodemailer\")).default ?? (await import(\"nodemailer\"));\n  } catch {\n    throw new Error(\"当前环境无法加载 nodemailer，无法发送邮件；请改用其他渠道或安装 nodemailer\");\n  }\n  const service = String(config.emailService ?? \"\").trim();\n  const transporter = nodemailer.createTransport(service !== \"\"\n    ? { service, auth: { user, pass } }\n    : {\n        host: String(config.emailHost ?? \"\").trim() || \"smtp.\" + user.split(\"@\")[1],\n        port: Number(config.emailPort) > 0 ? Number(config.emailPort) : (String(config.emailSecure ?? \"\") === \"true\" ? 465 : 587),\n        secure: String(config.emailSecure ?? \"\") === \"true\",\n        auth: { user, pass },\n      });\n  const recipients = to.split(/[;；]/).map((s) => s.trim()).filter(Boolean);\n  const info = await transporter.sendMail({\n    from: `\"chicheng-push\" <${user}>`,\n    to: recipients.join(\", \"),\n    subject: title,\n    html: content.replace(/\\n/g, \"<br/>\"),\n  });\n  transporter.close();\n  if (!info.messageId) throw new Error(\"邮件发送未返回 messageId\");\n  return `邮件已发送 (${info.messageId})`;\n}\n\n// ---------------------------------------------------------------- send core\n\n/** Send one channel; returns { id, name, type, ok, message? }. */\nasync function sendChannel(channel, title, content) {\n  try {\n    const sender = senderForType(channel.type);\n    const message = await sender(channel.config ?? {}, title, content);\n    return { id: channel.id, name: channel.name, type: channel.type, ok: true, message };\n  } catch (error) {\n    return { id: channel.id, name: channel.name, type: channel.type, ok: false, error: errorText(error) };\n  }\n}\n\n/** Resolve the target channel list of a `channels` select (undefined | 'all' | string[]). */\nfunction resolveTargets(channels) {\n  const active = store.channels.filter((c) => c.enabled !== false);\n  if (channels === undefined || channels === null || channels === \"all\" || channels === \"*\") return active;\n  const ids = Array.isArray(channels) ? channels.map(String) : [String(channels)];\n  if (ids.length === 0) return active;\n  if (ids.includes(\"all\") || ids.includes(\"*\")) return active;\n  const byId = new Map(active.map((c) => [c.id, c]));\n  const byName = new Map(active.map((c) => [c.name, c]));\n  return ids.map((id) => byId.get(id) ?? byName.get(id)).filter(Boolean);\n}\n\n/**\n * Send a notification. This is the face exposed both as the `pushNotifier`\n * service (host plugins) and as the /push/api/send route (any caller).\n */\nasync function sendNotification({ title, content, channels }) {\n  const titleText = String(title ?? \"\").trim();\n  const contentText = String(content ?? \"\");\n  const targets = resolveTargets(channels);\n  const results = [];\n  for (const channel of targets) {\n    results.push(await sendChannel(channel, titleText, contentText));\n  }\n  return {\n    ok: results.length > 0 && results.every((r) => r.ok),\n    total: results.length,\n    sent: results.filter((r) => r.ok).length,\n    results,\n  };\n}\n\n// ---------------------------------------------------------------- public shapes\n\nfunction publicChannel(channel) {\n  return {\n    id: channel.id,\n    name: channel.name,\n    type: channel.type,\n    enabled: channel.enabled !== false,\n    config: channel.config ?? {},\n    createdAt: channel.createdAt ?? null,\n    updatedAt: channel.updatedAt ?? null,\n  };\n}\n\nfunction publicTypes() {\n  return CHANNEL_TYPES.map((t) => ({\n    id: t.id,\n    label: t.label,\n    help: t.help ?? \"\",\n    fields: t.fields,\n  }));\n}\n\n// ---------------------------------------------------------------- API wire\n\nconst MAX_BODY_BYTES = 1 << 20;\n\nclass PushError extends Error {\n  constructor(code, message, status = 400) {\n    super(message);\n    this.code = code;\n    this.status = status;\n  }\n}\n\nasync function readJsonBody(req) {\n  const chunks = [];\n  let total = 0;\n  for await (const chunk of req) {\n    const buffer = Buffer.from(chunk);\n    total += buffer.length;\n    if (total > MAX_BODY_BYTES) throw new PushError(\"bad-request\", \"request body too large\", 413);\n    chunks.push(buffer);\n  }\n  const text = Buffer.concat(chunks).toString(\"utf8\");\n  if (text.trim() === \"\") return {};\n  try {\n    return JSON.parse(text);\n  } catch {\n    throw new PushError(\"bad-request\", \"request body is not valid JSON\");\n  }\n}\n\nfunction writeJson(res, status, body) {\n  const payload = JSON.stringify(body);\n  res.writeHead(status, { \"content-type\": \"application/json; charset=utf-8\", \"cache-control\": \"no-cache\" });\n  res.end(payload);\n}\n\nfunction writeOk(res, value) {\n  writeJson(res, 200, { ok: true, value });\n}\n\nfunction writeError(res, error) {\n  if (error instanceof PushError) {\n    writeJson(res, error.status, { ok: false, error: { code: error.code, message: error.message } });\n    return;\n  }\n  const message = error instanceof Error ? error.message : String(error);\n  writeJson(res, 500, { ok: false, error: { code: \"internal\", message } });\n}\n\nfunction header(headers, key) {\n  const value = headers[key];\n  return typeof value === \"string\" ? value : undefined;\n}\n\nfunction parseAuthority(authority) {\n  try {\n    return new URL(`http://${authority}`);\n  } catch {\n    return undefined;\n  }\n}\n\nfunction isLoopbackHostname(hostname) {\n  if (hostname === \"localhost\" || hostname === \"[::1]\") return true;\n  const parts = hostname.split(\".\");\n  return parts.length === 4 && parts[0] === \"127\" && parts.every((part) => /^\\d{1,3}$/.test(part) && Number(part) <= 255);\n}\n\nfunction isTrustedApiRequest(request, trustedHosts) {\n  const host = header(request.headers, \"host\");\n  if (host === undefined) return false;\n  const hostUrl = parseAuthority(host);\n  if (hostUrl === undefined) return false;\n  const hosts = Array.isArray(trustedHosts) ? trustedHosts : [];\n  const trusted = hosts.some((entry) => {\n    const entryUrl = parseAuthority(entry);\n    if (entryUrl === undefined) return false;\n    return entryUrl.hostname === hostUrl.hostname && (entryUrl.port === \"\" || entryUrl.port === hostUrl.port);\n  });\n  if (!isLoopbackHostname(hostUrl.hostname) && !trusted) return false;\n  if (header(request.headers, \"sec-fetch-site\") === \"cross-site\") return false;\n  const origin = header(request.headers, \"origin\");\n  if (origin === undefined) return true;\n  try {\n    return new URL(origin).host === hostUrl.host;\n  } catch {\n    return false;\n  }\n}\n\n// ---------------------------------------------------------------- API handlers\n\n/** Validate and normalize a channel payload from the UI or API. */\nfunction normalizeChannel(payload) {\n  if (!isPlainObject(payload)) throw new PushError(\"bad-request\", \"channel object required\");\n  const nameValue = payload.name;\n  if (typeof nameValue !== \"string\" || nameValue.trim() === \"\") {\n    throw new PushError(\"bad-request\", \"渠道名称不能为空\");\n  }\n  const typeValue = payload.type;\n  if (typeof typeValue !== \"string\" || !TYPE_MAP.has(typeValue)) {\n    throw new PushError(\"bad-request\", `不支持的渠道类型 \"${typeValue}\"`);\n  }\n  const config = isPlainObject(payload.config) ? payload.config : {};\n  const def = TYPE_MAP.get(typeValue);\n  for (const field of def.fields) {\n    if (field.required && !String(config[field.key] ?? \"\").trim()) {\n      throw new PushError(\"bad-request\", `缺少必填项：${field.label}`);\n    }\n  }\n  return {\n    id: typeof payload.id === \"string\" && payload.id !== \"\" ? payload.id : null,\n    name: nameValue.trim(),\n    type: typeValue,\n    enabled: payload.enabled !== false,\n    config,\n  };\n}\n\nfunction buildApi(ctx) {\n  return {\n    list: async () => {\n      return { channels: store.channels.map(publicChannel) };\n    },\n\n    types: async () => {\n      return { types: publicTypes() };\n    },\n\n    save: async (payload) => {\n      const normalized = normalizeChannel(payload?.channel ?? payload);\n      const nowIso = new Date().toISOString();\n      let savedIndex;\n      if (normalized.id !== null) {\n        const existing = store.channels.find((c) => c.id === normalized.id);\n        if (!existing) throw new PushError(\"not-found\", `渠道 \"${normalized.id}\" 不存在`, 404);\n        savedIndex = store.channels.indexOf(existing);\n        Object.assign(existing, {\n          name: normalized.name,\n          type: normalized.type,\n          enabled: normalized.enabled,\n          config: normalized.config,\n          updatedAt: nowIso,\n        });\n      } else {\n        store.channels.push({\n          id: `ch-${randomUUID().slice(0, 8)}`,\n          name: normalized.name,\n          type: normalized.type,\n          enabled: normalized.enabled,\n          config: normalized.config,\n          createdAt: nowIso,\n          updatedAt: nowIso,\n        });\n        savedIndex = store.channels.length - 1;\n      }\n      scheduleSave();\n      return { channel: publicChannel(store.channels[savedIndex]) };\n    },\n\n    remove: async (payload) => {\n      const id = payload?.id;\n      if (typeof id !== \"string\" || id === \"\") throw new PushError(\"bad-request\", \"missing id\");\n      const index = store.channels.findIndex((c) => c.id === id);\n      if (index === -1) throw new PushError(\"not-found\", `渠道 \"${id}\" 不存在`, 404);\n      store.channels.splice(index, 1);\n      scheduleSave();\n      return { id, deleted: true };\n    },\n\n    toggle: async (payload) => {\n      const id = payload?.id;\n      if (typeof id !== \"string\" || id === \"\") throw new PushError(\"bad-request\", \"missing id\");\n      const channel = store.channels.find((c) => c.id === id);\n      if (!channel) throw new PushError(\"not-found\", `渠道 \"${id}\" 不存在`, 404);\n      channel.enabled = payload.enabled !== false;\n      channel.updatedAt = new Date().toISOString();\n      scheduleSave();\n      return { id, enabled: channel.enabled, channel: publicChannel(channel) };\n    },\n\n    test: async (payload) => {\n      const id = payload?.id;\n      if (typeof id !== \"string\" || id === \"\") throw new PushError(\"bad-request\", \"missing id\");\n      const channel = store.channels.find((c) => c.id === id);\n      if (!channel) throw new PushError(\"not-found\", `渠道 \"${id}\" 不存在`, 404);\n      const when = new Date().toLocaleString();\n      const result = await sendChannel(channel, \"dsh 推送测试\", `这是一条来自 dsh 推送插件的测试消息。\\n渠道：${channel.name}（${channel.type}）\\n发送时间：${when}`);\n      return { result };\n    },\n\n    send: async (payload) => {\n      const title = payload?.title ?? \"\";\n      const content = payload?.content ?? \"\";\n      if (!String(title).trim() && !String(content).trim()) {\n        throw new PushError(\"bad-request\", \"title 与 content 至少提供一个\");\n      }\n      return await sendNotification({ title, content, channels: payload?.channels });\n    },\n  };\n}\n\n/** The service other host plugins inject/read: the programmatic push face. */\nfunction buildService() {\n  return {\n    list() {\n      return store.channels.map(publicChannel);\n    },\n    types() {\n      return publicTypes();\n    },\n    send(payload) {\n      if (typeof payload === \"string\") {\n        // Convenience overload: send(\"标题\", \"内容\", [\"ch-...\"]) is handled\n        // through a separate function below; a bare string means title-only.\n        return sendNotification({ title: payload, content: \"\", channels: undefined });\n      }\n      if (!isPlainObject(payload)) throw new Error(\"pushNotifier.send 需要 { title, content, channels? }\");\n      return sendNotification(payload);\n    },\n    sendText(title, content, channels) {\n      return sendNotification({ title, content, channels });\n    },\n    async test(id) {\n      const channel = store.channels.find((c) => c.id === id);\n      if (!channel) throw new Error(`渠道 \"${id}\" 不存在`);\n      return sendChannel(channel, \"dsh 推送测试\", `这是一条来自 dsh 推送插件的测试消息。\\n渠道：${channel.name}（${channel.type}）`);\n    },\n  };\n}\n\n// ---------------------------------------------------------------- plugin body\n\nasync function apply(ctx) {\n  await loadStore();\n  const fence = (req) => {\n    try {\n      return isTrustedApiRequest(req, ctx.webRuntime?.trustedHosts ?? []);\n    } catch {\n      return false;\n    }\n  };\n  const api = buildApi(ctx);\n\n  ctx.effect(() => ctx.webServer.register({\n    kind: \"prefix\",\n    path: \"/push/api\",\n    handler: async (req, res) => {\n      if (!fence(req)) {\n        writeJson(res, 403, { ok: false, error: { code: \"forbidden\", message: \"forbidden\" } });\n        return;\n      }\n      if (req.method !== \"POST\") {\n        writeJson(res, 405, { ok: false, error: { code: \"method-error\", message: \"method not allowed\" } });\n        return;\n      }\n      const pathname = new URL(req.url ?? \"/\", \"http://push.invalid\").pathname;\n      const tail = pathname.startsWith(\"/push/api/\") ? pathname.slice(10) : undefined;\n      if (tail === undefined || tail.includes(\"/\") || tail === \"\") {\n        writeError(res, new PushError(\"not-found\", \"unknown push API method\", 404));\n        return;\n      }\n      try {\n        const payload = await readJsonBody(req);\n        const handler = api[tail];\n        if (typeof handler !== \"function\") throw new PushError(\"not-found\", `unknown push API method \"${tail}\"`, 404);\n        writeOk(res, await handler(payload));\n      } catch (error) {\n        writeError(res, error);\n      }\n    },\n  }), \"chicheng-push: /push/api routes\");\n\n  ctx.effect(() => () => {\n    void flushStore();\n  }, \"chicheng-push: teardown\");\n\n  // Programmatic face for other plugins: `ctx.get(\"pushNotifier\")?.send(...)`.\n  ctx.provide(\"pushNotifier\", buildService());\n\n  ctx.logger?.info?.(\"[chicheng-push] started, data root: \" + DATA_ROOT);\n}\n\nexport { apply, inject, name };"
