      "path": "test/smoke.mjs",
      "content": "/**\n * chicheng-push smoke test (no dsh host): drives apply() with a fake ctx,\n * exercises the /push/api routes through real request/response objects, and\n * verifies webhook + serverChan-style sending against a local HTTP server.\n */\nimport { createServer } from \"node:http\";\nimport { mkdtempSync, readFileSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { Readable } from \"node:stream\";\n\n// Set DSH_HOME BEFORE importing the plugin (its module top-level computes\n// DATA_ROOT from process.env.DSH_HOME).\nprocess.env.DSH_HOME = mkdtempSync(join(tmpdir(), \"dsh-push-smoke-\"));\nconst { apply } = await import(new URL(\"../lib/index.js\", import.meta.url).href);\n\n// ---------------------------------------------------------------- fake ctx\n\nconst registered = [];\nconst log = [];\nconst fakeCtx = {\n  webServer: {\n    register(entry) {\n      registered.push(entry);\n      return () => {};\n    },\n  },\n  webRuntime: { trustedHosts: [] },\n  logger: { info: (...args) => log.push([\"info\", ...args]) },\n  effect(cb) {\n    return cb();\n  },\n  provide(name, value) {\n    fakeCtx._provided = fakeCtx._provided || {};\n    fakeCtx._provided[name] = value;\n    return () => {};\n  },\n};\n\n// ---------------------------------------------------------------- helpers\n\nlet pendingHttpBodies = [];\nconst httpServer = createServer((req, res) => {\n  let body = \"\";\n  req.on(\"data\", (c) => (body += c));\n  req.on(\"end\", () => {\n    pendingHttpBodies.push({ url: req.url, headers: req.headers, body });\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({ code: 0, ok: true }));\n  });\n});\n\nfunction request(entry, method, path, payload, headers = {}) {\n  const req = new Readable({ read() {} });\n  req.method = method;\n  req.url = path;\n  req.headers = { host: \"127.0.0.1:3080\", ...headers };\n  if (payload !== undefined) req.push(JSON.stringify(payload));\n  req.push(null);\n  const res = {\n    _status: 0,\n    _body: \"\",\n    writeHead(status, h) { this._status = status; this._headers = h; },\n    end(body) { this._body = body; },\n  };\n  return entry.handler(req, res).then(() => ({\n    status: res._status,\n    body: JSON.parse(res._body || \"{}\"),\n  }));\n}\n\n// ---------------------------------------------------------------- run\n\nlet failures = 0;\nconst check = (label, cond, extra = \"\") => {\n  console.log(`${cond ? \"PASS\" : \"FAIL\"} ${label}${extra ? \" — \" + extra : \"\"}`);\n  if (!cond) failures += 1;\n};\n\nawait new Promise((r) => httpServer.listen(0, \"127.0.0.1\", r));\nconst port = httpServer.address().port;\n\nawait apply(fakeCtx, {});\n\nconst pushEntry = registered.find((e) => e.path === \"/push/api\");\ncheck(\"route registered at /push/api\", !!pushEntry, pushEntry ? pushEntry.kind : \"none\");\ncheck(\"pushNotifier service provided\", !!fakeCtx._provided?.pushNotifier);\n\n// fence: cross-site origin must be refused\nconst crossSite = await request(pushEntry, \"POST\", \"/push/api/list\", {}, { origin: \"https://evil.example\", \"sec-fetch-site\": \"cross-site\" });\ncheck(\"cross-site request refused\", crossSite.status === 403, `status=${crossSite.status}`);\n\n// types\nconst types = await request(pushEntry, \"POST\", \"/push/api/types\", {});\ncheck(\"types API returns >0 types\", Array.isArray(types.body.value?.types) && types.body.value.types.length > 10);\n\n// save webhook channel (points at our local server)\nawait request(pushEntry, \"POST\", \"/push/api/save\", {\n  channel: {\n    name: \"本地测试 Webhook\",\n    type: \"webhook\",\n    enabled: true,\n    config: {\n      webhookUrl: `http://127.0.0.1:${port}/hook$title`,\n      webhookMethod: \"POST\",\n      webhookContentType: \"application/json\",\n      webhookBody: '{\"title\":\"$title\",\"content\":\"$content\"}',\n    },\n  },\n});\n\n// save serverChan channel (missing required key -> must 400)\nconst bad = await request(pushEntry, \"POST\", \"/push/api/save\", {\n  channel: { name: \"坏渠道\", type: \"serverChan\", config: {} },\n});\ncheck(\"required field enforced\", bad.status === 400, `status=${bad.status}`);\n\nconst list1 = await request(pushEntry, \"POST\", \"/push/api/list\", {});\nconst channel = list1.body.value.channels[0];\ncheck(\"channel persisted\", list1.body.value.channels.length === 1, JSON.stringify(list1.body.value.channels.map((c) => c.name)));\n\n// toggle off then on\nawait request(pushEntry, \"POST\", \"/push/api/toggle\", { id: channel.id, enabled: false });\nconst list2 = await request(pushEntry, \"POST\", \"/push/api/list\", {});\ncheck(\"toggle disables channel\", list2.body.value.channels[0].enabled === false);\n\n// send with channels:\"all\" -> disabled channel skipped, webhook hits local server\nconst sendRes = await request(pushEntry, \"POST\", \"/push/api/send\", {\n  title: \"Smoke 标题\",\n  content: \"Smoke 内容行1\\n行2\",\n  channels: \"all\",\n});\ncheck(\"send ok when no enabled channel\", sendRes.body.value.ok === false && sendRes.body.value.total === 0, JSON.stringify(sendRes.body.value));\n\nawait request(pushEntry, \"POST\", \"/push/api/toggle\", { id: channel.id, enabled: true });\nconst sendRes2 = await request(pushEntry, \"POST\", \"/push/api/send\", { title: \"Smoke2\", content: \"内容\", channels: \"all\" });\ncheck(\"send hits enabled webhook\", sendRes2.body.value.ok === true && sendRes2.body.value.sent === 1, JSON.stringify(sendRes2.body.value));\ncheck(\"webhook received one POST\", pendingHttpBodies.length === 1, `got=${pendingHttpBodies.length}`);\nif (pendingHttpBodies[0]) {\n  const hit = pendingHttpBodies[0];\n  check(\"webhook URL variable substituted\", hit.url === `/hookSmoke2`, hit.url);\n  const parsed = JSON.parse(hit.body);\n  check(\"webhook body variables substituted\", parsed.title === \"Smoke2\" && parsed.content === \"内容\", hit.body);\n  check(\"webhook content-type json\", hit.headers[\"content-type\"] === \"application/json\", hit.headers[\"content-type\"]);\n}\n\n// simple text send via service\nconst svcSend = await fakeCtx._provided.pushNotifier.sendText(\"服务标题\", \"服务内容\", \"all\");\ncheck(\"pushNotifier.sendText works\", svcSend.sent === 1 && svcSend.ok, JSON.stringify(svcSend.results));\ncheck(\"second webhook POST captured\", pendingHttpBodies.length === 2, `got=${pendingHttpBodies.length}`);\n\n// remove\nconst rm = await request(pushEntry, \"POST\", \"/push/api/remove\", { id: channel.id });\ncheck(\"remove ok\", rm.body.value.deleted === true);\nconst list3 = await request(pushEntry, \"POST\", \"/push/api/list\", {});\ncheck(\"channel gone after remove\", list3.body.value.channels.length === 0);\n\n// persisted store file exists (await the 150ms debounced flush)\nawait new Promise((r) => setTimeout(r, 400));\nconst storeRaw = readFileSync(join(process.env.DSH_HOME, \"push\", \"channels.json\"), \"utf8\");\ncheck(\"store file persisted\", storeRaw.includes('\"channels\"'));\n\nhttpServer.closeAllConnections?.();\nhttpServer.close();\nconsole.log(failures === 0 ? \"\\nALL PASS\" : `\\n${failures} FAILURES`);\nprocess.exit(failures === 0 ? 0 : 1);"
    },
