      "path": "test/types.test.mjs",
      "content": "/**\n * chicheng-push registry consistency test (no dsh host, no network):\n * drives apply() with a fake ctx and verifies that every channel type's\n * schema (fields returned by /push/api/types) is well-formed and that the\n * store-level validation rejects incomplete payloads.\n */\nimport { mkdtempSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { Readable } from \"node:stream\";\n\nprocess.env.DSH_HOME = mkdtempSync(join(tmpdir(), \"dsh-push-types-\"));\nconst { apply } = await import(new URL(\"../lib/index.js\", import.meta.url).href);\n\nconst registered = [];\nconst fakeCtx = {\n  webServer: {\n    register(entry) {\n      registered.push(entry);\n      return () => {};\n    },\n  },\n  webRuntime: { trustedHosts: [] },\n  logger: { info: () => {} },\n  effect(cb) {\n    return cb();\n  },\n  provide(name, value) {\n    fakeCtx._provided = fakeCtx._provided || {};\n    fakeCtx._provided[name] = value;\n    return () => {};\n  },\n};\n\nfunction request(entry, method, path, payload) {\n  const req = new Readable({ read() {} });\n  req.method = method;\n  req.url = path;\n  req.headers = { host: \"127.0.0.1:3080\" };\n  if (payload !== undefined) req.push(JSON.stringify(payload));\n  req.push(null);\n  const res = {\n    _status: 0,\n    _body: \"\",\n    writeHead(status) { this._status = status; },\n    end(body) { this._body = body; },\n  };\n  return entry.handler(req, res).then(() => ({\n    status: res._status,\n    body: JSON.parse(res._body || \"{}\"),\n  }));\n}\n\nlet failures = 0;\nconst check = (label, cond, extra = \"\") => {\n  console.log(`${cond ? \"PASS\" : \"FAIL\"} ${label}${extra ? \" — \" + extra : \"\"}`);\n  if (!cond) failures += 1;\n};\n\nawait apply(fakeCtx, {});\nconst pushEntry = registered.find((e) => e.path === \"/push/api\");\nconst typesRes = await request(pushEntry, \"POST\", \"/push/api/types\", {});\nconst types = typesRes.body.value?.types ?? [];\n\ncheck(\"types API returns a non-empty list\", types.length > 10, `count=${types.length}`);\n\nconst fieldKeys = new Set([\"key\", \"label\", \"type\"]);\nconst validFieldTypes = new Set([\"text\", \"password\", \"textarea\", \"number\", \"select\"]);\nfor (const t of types) {\n  const idOk = typeof t.id === \"string\" && t.id !== \"\";\n  check(`type ${t.id}: id`, idOk);\n  check(`type ${t.id}: label`, typeof t.label === \"string\" && t.label !== \"\");\n  check(`type ${t.id}: fields array`, Array.isArray(t.fields) && t.fields.length > 0);\n  for (const f of t.fields ?? []) {\n    check(`type ${t.id} field ${f.key}: keys`, Object.keys(f).every((k) => fieldKeys.has(k) || k === \"options\" || k === \"placeholder\" || k === \"help\" || k === \"required\" || k === \"default\"));\n    check(`type ${t.id} field ${f.key}: type valid`, validFieldTypes.has(f.type), f.type);\n    if (f.type === \"select\") {\n      check(`type ${t.id} field ${f.key}: select options`, Array.isArray(f.options) && f.options.length > 0);\n    }\n  }\n}\n\n// save without a required field must be rejected\nconst bad = await request(pushEntry, \"POST\", \"/push/api/save\", {\n  channel: { name: \"缺字段\", type: \"serverChan\", config: {} },\n});\ncheck(\"required field enforced (serverChan key)\", bad.status === 400, `status=${bad.status}`);\n\nconst bad2 = await request(pushEntry, \"POST\", \"/push/api/save\", {\n  channel: { name: \"缺字段\", type: \"telegramBot\", config: { telegramBotToken: \"t\" } },\n});\ncheck(\"required field enforced (telegram chat id)\", bad2.status === 400, `status=${bad2.status}`);\n\nconsole.log(failures === 0 ? \"\\nALL PASS\" : `\\n${failures} FAILURES`);\nprocess.exit(failures === 0 ? 0 : 1);\n"
    }
